import { z } from "zod";

export const requiredText = (message: string) => z.string().trim().min(1, message);
export const optionalText = z.string().trim();
export const quantity = z.number({ error: "Unesite količinu." }).int("Količina mora biti cijeli broj.");
export const price = z.number({ error: "Unesite cijenu." }).min(0, "Cijena ne može biti negativna.");
export const percent = z
  .number({ error: "Unesite postotak." })
  .min(0, "Postotak ne može biti negativan.")
  .max(100, "Postotak može biti najviše 100.");

// Generated by the client once per submission (crypto.randomUUID) and reused on retries, so a double click
// or a network retry is booked only once.
export const idempotencyKey = z.uuid("Neispravan ključ operacije.");

// A text id passed to a Server Action next to the form values (e.g. "PRD-1021", "CUS-1001", "SUP-1").
export const recordId = z.string().trim().min(1).max(64);
// A numeric id (categories, listings).
export const numericId = z.number().int().positive();
